css:
.fx-stk2{width:min(560px,100%)}
.fx-stk2 .box{height:min(72vh,480px);overflow:auto;border:1px solid var(--border);border-radius:var(--radius);background:color-mix(in srgb,var(--primary) 5%,var(--surface));padding:1em 1em 8em}
.fx-stk2 .hint{text-align:center;font-size:.82em;opacity:.55;padding:.4em 0 1em}
.fx-stk2 .c{position:sticky;top:calc(.8em + var(--i)*1.5em);height:15em;margin-bottom:2.2em;border-radius:calc(var(--radius)*1.2);padding:1.4em 1.5em;display:flex;flex-direction:column;justify-content:space-between;color:var(--on-primary);background:var(--bg);transform-origin:50% 0;will-change:transform;box-shadow:0 -10px 30px -12px color-mix(in srgb,#000 35%,transparent)}
.fx-stk2 .c:nth-of-type(1){--bg:var(--primary)}.fx-stk2 .c:nth-of-type(2){--bg:color-mix(in srgb,var(--primary) 55%,var(--accent))}.fx-stk2 .c:nth-of-type(3){--bg:var(--accent);color:var(--on-accent)}.fx-stk2 .c:nth-of-type(4){--bg:var(--secondary)}
.fx-stk2 .c b{font:700 .8em var(--font-body);letter-spacing:.18em;opacity:.8}
.fx-stk2 .c h3{font-size:1.7em;margin:.2em 0}.fx-stk2 .c p{opacity:.9;max-width:34ch}
.fx-stk2 .c .n{font:700 3em/1 var(--font-heading);opacity:.35;align-self:flex-end}

js:
(function(){var box=document.querySelector('.fx-stk2 .box'),cs=[].slice.call(box.querySelectorAll('.c')),rm=matchMedia('(prefers-reduced-motion:reduce)').matches,tk=false;
function up(){tk=false;if(rm)return;var bt=box.getBoundingClientRect().top;
 cs.forEach(function(c,i){var n=cs[i+1];if(!n){return}var st=parseFloat(getComputedStyle(c).top),h=c.offsetHeight,d=n.getBoundingClientRect().top-(bt+st),p=1-Math.min(1,Math.max(0,d/h));
  c.style.transform='scale('+(1-p*.07)+')';c.style.filter='brightness('+(1-p*.28)+')'})}
box.addEventListener('scroll',function(){if(!tk){tk=true;requestAnimationFrame(up)}},{passive:true});up()})();
